import {activePolicyPetitions} from './petitions.js?v=direct-model-paint-2';
import {showPolicyPetitions} from './petitions-ui.js?v=direct-model-paint-2';
import {conservationReport} from './conservation.js?v=direct-model-paint-2';
import {educationReport,educationServiceDemand} from './education.js?v=direct-model-paint-2';
import {healthReport} from './health.js?v=direct-model-paint-2';
import {SERVICES,DEPARTMENTS,ORDINANCES,changeCivic,civicSpending,ordinanceCost,ordinanceRevenue} from './civic.js?v=direct-model-paint-2';
import {recompute} from './engine.js?v=direct-model-paint-2';
const teachingGap=(c,type)=>{const d=educationServiceDemand(c,type);return d.share>0&&(c.stats[d.field]||0)<50;};
export function civicAdvice(c){const s=c.stats;if(s.strikes.length)return `${s.strikes.map(k=>DEPARTMENTS[k]).join(', ')} workers are on strike. Restore funding to 100% and run one month to resume service.`;if(s.population&&s.healthCoverage<60)return 'Residents need healthcare. Build a powered hospital on their road network and fund Healthcare in Civic services.';if(s.population&&teachingGap(c,'school'))return 'Children lack school places. Add powered schools on their road networks and check education funding.';if(s.population&&teachingGap(c,'college'))return 'Young adults lack college places. Schools cannot replace colleges; connect and fund a college.';if(s.population&&educationServiceDemand(c,'library').share>0&&s.adultEducationCoverage<50)return 'Adults need places to retain their education. Connect and fund libraries or museums on their neighborhood roads.';if(s.averageCrime>25)return 'Crime is troubling residents. Place police near homes, check jail capacity, or fund neighborhood watch.';if(s.population&&s.fireCoverage<50)return 'Fire coverage is weak. Add fire stations near homes and maintain their funding. Water lowers flammability.';return 'Service coverage is improving. Watch the budget while education and life expectancy change over time.';}
export function showCivic(ui){
 const {city,dialog,close,update,save,clearUndo,notify,review,setTool,setLayer}=ui,c=city(),s=c.stats,$=v=>document.querySelector(v),fmt=v=>'§'+Math.round(v).toLocaleString();
 const petitions=[{condition:s.healthCoverage<60,who:'Residents’ health committee',text:'Our neighborhoods need better access to hospital care.',tool:'hospital'},{condition:teachingGap(c,'school'),who:'Parents’ association',text:'Give our children a school connected to their neighborhood.',tool:'school'},{condition:teachingGap(c,'college'),who:'Prospective college students',text:'We need college places connected to our neighborhoods.',tool:'college'},{condition:s.averageCrime>25,who:'Neighborhood council',text:'We need a police presence closer to our homes.',tool:'police'},{condition:s.fireCoverage<50,who:'Fire chief',text:'Station coverage is thin. Place a fire station near uncovered homes.',tool:'fire'}].filter(p=>p.condition&&s.population>0);
 dialog('Civic services & advisors',`<p>${civicAdvice(c)}</p><button id="policyPetitions">Meet policy petitioners · ${activePolicyPetitions(c).length} awaiting a decision</button><div class="metric-grid"><div><small>Crime</small><strong>${Math.round(s.averageCrime)} / 100</strong></div><div><small>Education</small><strong>${Math.round(s.education)} / 100</strong></div><div><small>Life expectancy</small><strong>${s.lifeExpectancy.toFixed(1)} years</strong></div><div><small>Aura · resident wellbeing</small><strong>${Math.round(s.aura)} / 100</strong></div></div><p>Education and life expectancy change gradually over years. Coverage changes immediately when buildings connect or funding changes.</p>${conservationReport(c)}${healthReport(c)}${educationReport(c)}<h3>Service funding</h3><div class="service-funding">${Object.entries(DEPARTMENTS).map(([k,name])=>`<label>${name} · <strong id="civicValue-${k}">${c.civic.funding[k]}%</strong>${s.strikes.includes(k)?' · ON STRIKE':''}<input type="range" id="civicFunding-${k}" min="0" max="150" step="5" value="${c.civic.funding[k]}"></label>`).join('')}</div><p class="fine">Below 50% funding for six months can cause a strike. Restore 100% and run one month to end it. Services need electricity and a road within four tiles. Stations gain radius and effectiveness with funding; hospitals and education buildings gain capacity.</p><h3>Ordinances</h3><p>Policies can be enacted or repealed here. Costs continue while enabled. Carpooling currently avoids ${Math.round(s.carpoolVehiclesSaved||0)} private-car trips; air pollution averages ${Math.round(s.averagePollution)} / 100.</p>${Object.entries(ORDINANCES).map(([k,o])=>`<label class="ordinance"><input id="ordinance-${k}" type="checkbox" ${c.civic.ordinances[k]?'checked':''}><span>${o.name} · ${o.income?'Revenue varies with car commuting':fmt(ordinanceCost(c,k)*12)+'/year ('+fmt(ordinanceCost(c,k))+'/month)'}<br><small>${o.description}</small></span></label>`).join('')}<p id="civicPreview" aria-live="polite"></p><button class="primary" id="applyCivic">Apply service budget & ordinances</button><p>Crime lowers local land value and tax receipts. Policing, education and Neighborhood watch can help properties recover. Inspect a tile to see its crime-related value loss.</p><h3>Coverage & buildings</h3><p>Compare school, college and adult learning access separately: one service cannot replace another. These maps show available places, not attained education. Age demand uses the city’s current age mix across occupied homes. Facility markers identify operating and inactive buildings; libraries and museums share adult demand.</p><div class="actions"><button data-civic-layer="police">Police coverage · ${Math.round(s.policeCoverage)}%</button><button data-civic-layer="fire">Fire coverage · ${Math.round(s.fireCoverage)}%</button><button data-civic-layer="crime">Crime map</button><button data-civic-layer="flammability">Flammability</button><button data-civic-layer="health">Healthcare · ${Math.round(s.healthCoverage)}%</button><button data-civic-layer="schoolAccess">School access · ${Math.round(s.childEducationCoverage)}%</button><button data-civic-layer="collegeAccess">College access · ${Math.round(s.collegeEducationCoverage)}%</button><button data-civic-layer="adultAccess">Adult learning access · ${Math.round(s.adultEducationCoverage)}%</button><button data-civic-layer="education">Education access · ${Math.round(s.educationCoverage)}%</button></div><div class="table-scroll"><table><thead><tr><th scope="col">Building</th><th scope="col">Operating / total</th><th scope="col">Build</th></tr></thead><tbody>${Object.entries(SERVICES).map(([k,v])=>`<tr><td>${v.name}</td><td>${s.activeServices[k]} / ${s.serviceCounts[k]}</td><td><button data-civic-build="${k}">${fmt(v.cost)}</button></td></tr>`).join('')}</tbody></table></div><p>Jail capacity: ${Math.round(s.serviceCapacities.jail)} / ${s.jailNeed} estimated places needed. Insufficient jail space reduces police effectiveness. Jails lower nearby residential land value.</p><h3>Petitions & briefings</h3>${petitions.map(p=>`<article class="milestone"><strong>${p.who}</strong><p>${p.text}</p><button data-civic-build="${p.tool}">Plan ${SERVICES[p.tool].name.toLowerCase()}</button></article>`).join('')||'<p>No urgent service requests. Keep capacity ahead of growth.</p>'}<h3>Serve residents · checkpoint</h3><ol><li>${s.policeCoverage>=50?'✓ ':''}Bring average police coverage to 50%.</li><li>${s.fireCoverage>=50?'✓ ':''}Bring average fire coverage to 50%.</li><li>${s.healthCoverage>=80?'✓ ':''}Supply healthcare to 80% of residents.</li><li>${s.educationCoverage>=60?'✓ ':''}Bring education access to 60% and track learning over time.</li></ol><p class="fine">Coverage and capacities are provisional. Age cohorts, full advisor dialogue, and the complete ordinance catalog remain later refinements.</p><button id="reviewCivic">Give milestone 4 feedback</button>`);
 $('#policyPetitions').onclick=()=>showPolicyPetitions(ui,()=>showCivic(ui));
 const draft=()=>({funding:Object.fromEntries(Object.keys(DEPARTMENTS).map(k=>[k,Number($(`#civicFunding-${k}`).value)])),ordinances:Object.fromEntries(Object.keys(ORDINANCES).map(k=>[k,$(`#ordinance-${k}`).checked]))});
 function preview(){const d=draft();for(const k of Object.keys(DEPARTMENTS))$(`#civicValue-${k}`).textContent=d.funding[k]+'%';const amount=Object.values(civicSpending(c,d.funding,d.ordinances)).reduce((a,b)=>a+b,0),current=Object.values(civicSpending(c)).reduce((a,b)=>a+b,0),receipts=Object.values(ordinanceRevenue(c,d.ordinances)).reduce((a,b)=>a+b,0);$('#civicPreview').textContent=`Civic spending: ${fmt(amount)}/month. Ordinance revenue: ${fmt(receipts)}/month (${fmt(receipts*12)}/year at current commuting). Balance after policy budget changes: ${fmt(c.stats.balance+current-amount+receipts-(c.stats.ordinanceIncome||0))}/month. Policy effects may also change tax revenue.`;}
 for(const k of Object.keys(DEPARTMENTS))$(`#civicFunding-${k}`).oninput=preview;for(const k of Object.keys(ORDINANCES))$(`#ordinance-${k}`).onchange=preview;
 $('#applyCivic').onclick=()=>{const d=draft(),result=changeCivic(c,d.funding,d.ordinances);if(!result.ok)return notify(result.error);recompute(c);clearUndo();update();save();notify('Service funding and ordinances applied.');showCivic(ui);};
 document.querySelectorAll('[data-civic-build]').forEach(b=>b.onclick=()=>{close();setTool(b.dataset.civicBuild);});document.querySelectorAll('[data-civic-layer]').forEach(b=>b.onclick=()=>{close();setLayer(b.dataset.civicLayer);});$('#reviewCivic').onclick=()=>review(4);preview();
}
